import*as T from'three';
import{ROOMS}from'../world/rooms.js';
/** Endpoint geometry is local to a rigid frame; view.root remains the room owner. */
export function airportEndpointContext(view,endpoint){return view?.endpointContext?.(endpoint?.roomId)??{frameRoot:view?.root,localRoom:ROOMS[endpoint?.roomId],airport:view?.airport};}
export function airportBase(view,scene,endpoint){const{frameRoot}=airportEndpointContext(view,endpoint);if(!frameRoot||!scene)throw Error('Missing airport endpoint frame');frameRoot.updateWorldMatrix(true,false);scene.updateWorldMatrix(true,false);const m=new T.Matrix4().copy(scene.matrixWorld).invert().multiply(frameRoot.matrixWorld),p=new T.Vector3(),q=new T.Quaternion(),s=new T.Vector3();m.decompose(p,q,s);const e=new T.Euler().setFromQuaternion(q,'YXZ');if(s.distanceTo(new T.Vector3(1,1,1))>1e-7||Math.abs(e.x)+Math.abs(e.z)>1e-7)throw Error('Airport base must preserve full-size level support');return m;}
export function airportScenePoint(view,scene,endpoint,point){const base=airportBase(view,scene,endpoint),p=new T.Vector3(point.x,point.y??.05,point.z).applyMatrix4(base);return{...point,x:p.x,y:p.y,z:p.z,...(point.yaw===undefined?{}:{yaw:new T.Euler().setFromRotationMatrix(base,'YXZ').y+point.yaw})};}
export function airportLocalPoint(view,scene,endpoint,point){const base=airportBase(view,scene,endpoint),yaw=new T.Euler().setFromRotationMatrix(base,'YXZ').y,p=new T.Vector3(point.x,point.y??.05,point.z).applyMatrix4(base.invert());return{...point,x:p.x,y:p.y,z:p.z,...(point.yaw===undefined?{}:{yaw:point.yaw-yaw})};}
export function airportEndpointWorld(view,scene,endpoint){const context=airportEndpointContext(view,endpoint),local=context.collisionWorld?.()??context.localRoom,world=view?.collisionWorld?.()??view?.residents?.collisionWorld?.();if(!view?.endpointContext?.(endpoint.roomId))return world??local;if(!world?.circles?.length)return local;return{...local,circles:[...(local.circles??[]),...world.circles.map(circle=>airportLocalPoint(view,scene,endpoint,circle))]};}
export function sceneLanding(view,scene,endpoint){return airportScenePoint(view,scene,endpoint,endpoint.landing);}
export function airportCamera(def,root){root.updateMatrix();if(root.position.lengthSq()===0&&root.rotation.x===0&&root.rotation.y===0&&root.rotation.z===0)return def;const result={...def};for(const key of['position','target'])if(def[key])result[key]=new T.Vector3(...def[key]).applyMatrix4(root.matrix).toArray();if(def.followBounds){const b=def.followBounds,points=[];for(const x of[b.minX,b.maxX])for(const z of[b.minZ,b.maxZ])points.push(new T.Vector3(x,0,z).applyMatrix4(root.matrix));result.followBounds={minX:Math.min(...points.map(p=>p.x)),maxX:Math.max(...points.map(p=>p.x)),minZ:Math.min(...points.map(p=>p.z)),maxZ:Math.max(...points.map(p=>p.z))};}return result;}

export function airportSpawn(root,spawn){root.updateWorldMatrix(true,false);const p=new T.Vector3(spawn.x,spawn.y??.05,spawn.z).applyMatrix4(root.matrixWorld),yaw=new T.Euler().setFromQuaternion(root.getWorldQuaternion(new T.Quaternion()),'YXZ').y+(spawn.yaw??0);return{...spawn,x:p.x,y:p.y,z:p.z,yaw};}
